//! M1 slice 1: vector's default implicit output written from typed tile records.
//!
//! Fixtures A and B (`tests/fixtures/m1_*.geojson`, generated by `tests/m1_fixture_gen.py`)
//! run end to end through the library facade on the compiled backend: portable, or the
//! native smoke run with `--features native-geospatial`. Hierarchy shape, roles, addresses
//! and the `_source_id` set must agree on both backends; bytes are compared only in the
//! evidence (`docs/VECTOR.md`: native triangulation and ordering may differ).
//!
//! A failed conversion publishes nothing: an invalid feature, a staged payload that no longer
//! matches its content record (C6), and an observer fault at `ready_to_publish` each leave no
//! output, no workspace and an existing destination unchanged.

use rusty_tiles::vector::{vector_to_archive, VectorLodOptions, VectorOptions, VectorRequest};
use rusty_tiles::{JobError, Observer, OutputPolicy, RunControl, RunEvent};
use serde_json::{json, Value};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    io::Read,
    path::{Path, PathBuf},
    sync::{Arc, Mutex},
};

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name)
}

fn options(levels: u8) -> VectorOptions {
    VectorOptions {
        reproducible: true,
        jobs: 1,
        max_features: 1,
        lod: VectorLodOptions {
            tolerance_metres: 0.5,
            levels,
        },
        ..VectorOptions::default()
    }
}

fn members(path: &Path) -> BTreeMap<String, Vec<u8>> {
    let mut archive = zip::ZipArchive::new(fs::File::open(path).unwrap()).unwrap();
    let mut out = BTreeMap::new();
    for i in 0..archive.len() {
        let mut file = archive.by_index(i).unwrap();
        let mut bytes = Vec::new();
        file.read_to_end(&mut bytes).unwrap();
        out.insert(file.name().to_owned(), bytes);
    }
    out
}

fn convert(input: &Path, output: &Path, options: VectorOptions) -> BTreeMap<String, Vec<u8>> {
    vector_to_archive(
        VectorRequest::new(input, output, options),
        &RunControl::default(),
    )
    .unwrap();
    members(output)
}

fn json_member(members: &BTreeMap<String, Vec<u8>>, name: &str) -> Value {
    serde_json::from_slice(&members[name]).unwrap()
}

/// The `_source_id` values present in the GLB payloads: the property table stores the JSON
/// text of the source id, so `"pt-alpha"` is written with its quotes.
fn source_ids(members: &BTreeMap<String, Vec<u8>>) -> BTreeSet<&'static str> {
    let mut found = BTreeSet::new();
    for (name, bytes) in members {
        if !name.ends_with(".glb") {
            continue;
        }
        assert_eq!(&bytes[..4], b"glTF", "{name} is a plain GLB");
        for id in ["\"pt-alpha\"", "\"ln-bravo\""] {
            if bytes.windows(id.len()).any(|w| w == id.as_bytes()) {
                found.insert(id);
            }
        }
    }
    found
}

/// The vertex counts of H's tiles in preorder, from `explicitRoot`.
fn shape(node: &Value, out: &mut Vec<u64>) {
    out.push(node["extras"]["vertices"].as_u64().unwrap_or(0));
    for child in node["children"].as_array().into_iter().flatten() {
        shape(child, out);
    }
}

fn vector_marker() -> Value {
    json!({"3DTILES_content_gltf_vector":{"vector":true}})
}

/// Fixture A: the whole hierarchy is one implicit root at `tileset.json` with three
/// levels, and the depth-1 and depth-2 tiles are rebased by non-zero deltas.
#[test]
fn fixture_a_is_one_implicit_root_at_tileset_json() {
    let root = tempfile::tempdir().unwrap();
    let output = root.path().join("a.3tz");
    let archive = convert(&fixture("m1_a.geojson"), &output, options(1));
    let names: Vec<&str> = archive.keys().map(String::as_str).collect();
    assert_eq!(
        names,
        [
            "@3dtilesIndex1@",
            "conversion.json",
            "geometry-reports.jsonl",
            "implicit-content/r0-0-0-0-0.glb",
            "implicit-content/r0-1-0-0-0.glb",
            "implicit-content/r0-1-1-0-0.glb",
            "implicit-content/r0-2-2-0-0.glb",
            "subtrees/r0-0-0-0.subtree",
            "tileset.json",
            "vector-build.json",
        ]
    );
    let tileset = json_member(&archive, "tileset.json");
    assert_eq!(tileset["asset"]["version"], "1.1");
    assert_eq!(
        tileset["extensionsUsed"],
        json!(["3DTILES_content_gltf_vector"])
    );
    assert!(tileset["schema"]["classes"].is_object());
    let tile = &tileset["root"];
    assert_eq!(
        tile["implicitTiling"],
        json!({"subdivisionScheme":"QUADTREE","subtreeLevels":3,"availableLevels":3,
            "subtrees":{"uri":"subtrees/r0-{level}-{x}-{y}.subtree"}})
    );
    assert_eq!(
        tile["content"],
        json!({"uri":"implicit-content/r0-{level}-{x}-{y}-0.glb","extensions":vector_marker()})
    );
    assert!(
        tile.get("extras").is_none(),
        "implicit roots carry no extras"
    );
    assert_eq!(tile["transform"].as_array().unwrap().len(), 16);
    let state = json_member(&archive, "vector-build.json");
    let mut vertices = Vec::new();
    shape(&state["explicitRoot"], &mut vertices);
    assert_eq!(
        vertices,
        [3, 1, 2, 9],
        "root, point leaf, line coarse, line leaf"
    );
    // Both identities reach the payloads.
    assert_eq!(
        source_ids(&archive),
        BTreeSet::from(["\"pt-alpha\"", "\"ln-bravo\""])
    );
    // Non-zero rebase deltas for the depth-1 and depth-2 tiles.
    let payloads = state["payloads"].as_object().unwrap();
    assert_eq!(payloads.len(), 4);
    let moved = payloads
        .values()
        .filter(|p| p["delta"].as_array().unwrap().iter().any(|v| v != 0.0))
        .count();
    assert_eq!(moved, 3);
}

/// Fixture B: a skeleton root in `tileset.json` with an explicit leaf published in place,
/// an L4 skeleton tile and, below it, an implicit root with a four-level subtree.
#[test]
fn fixture_b_crosses_the_subtree_boundary_under_a_skeleton() {
    let root = tempfile::tempdir().unwrap();
    let output = root.path().join("b.3tz");
    let archive = convert(&fixture("m1_b.geojson"), &output, options(4));
    let tileset = json_member(&archive, "tileset.json");
    let tile = &tileset["root"];
    assert!(
        tile.get("implicitTiling").is_none(),
        "the root is a skeleton"
    );
    let children = tile["children"].as_array().unwrap();
    assert_eq!(children.len(), 2);
    let leaf = &children[0];
    let leaf_uri = leaf["content"]["uri"].as_str().unwrap();
    assert!(leaf_uri.starts_with("t/") && leaf.get("children").is_none());
    assert!(
        archive.contains_key(leaf_uri),
        "explicit leaves stay in place"
    );
    let skeleton = &children[1];
    assert!(skeleton.get("implicitTiling").is_none());
    assert!(skeleton["content"]["uri"]
        .as_str()
        .unwrap()
        .starts_with("t/"));
    let implicit = &skeleton["children"][0];
    assert_eq!(implicit["implicitTiling"]["subtreeLevels"], 4);
    assert_eq!(implicit["implicitTiling"]["availableLevels"], 4);
    let id = implicit["content"]["uri"]
        .as_str()
        .unwrap()
        .strip_prefix("implicit-content/r")
        .unwrap()
        .split('-')
        .next()
        .unwrap();
    for level in 0..4 {
        let member = format!("implicit-content/r{id}-{level}-0-0-0.glb");
        assert!(archive.contains_key(&member), "{member}");
    }
    assert!(archive.contains_key(&format!("subtrees/r{id}-0-0-0.subtree")));
    let state = json_member(&archive, "vector-build.json");
    let mut vertices = Vec::new();
    shape(&state["explicitRoot"], &mut vertices);
    assert_eq!(vertices, [3, 1, 2, 3, 4, 5, 6], "one vertex per LOD level");
    assert_eq!(
        source_ids(&archive),
        BTreeSet::from(["\"pt-alpha\"", "\"ln-bravo\""])
    );
}

/// Fixture A's own archive is reused completely and republished unchanged.
#[test]
fn fixture_a_reuses_its_own_typed_hierarchy() {
    let root = tempfile::tempdir().unwrap();
    let first = root.path().join("first.3tz");
    let fresh = convert(&fixture("m1_a.geojson"), &first, options(1));
    let second = root.path().join("second.3tz");
    let reused = convert(
        &fixture("m1_a.geojson"),
        &second,
        VectorOptions {
            reuse_tileset: Some(first),
            ..options(1)
        },
    );
    let report = json_member(&reused, "conversion.json");
    assert_eq!(report["reuse"]["reusedTiles"], 4);
    assert_eq!(report["reuse"]["rebuiltContents"], 0);
    for (name, bytes) in &fresh {
        if !matches!(
            name.as_str(),
            "conversion.json" | "geometry-reports.jsonl" | "@3dtilesIndex1@"
        ) {
            assert_eq!(&reused[name], bytes, "{name}");
        }
    }
}

// ---- A failed conversion publishes nothing ----

fn workspaces(parent: &Path) -> Vec<PathBuf> {
    fs::read_dir(parent)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| {
            p.file_name()
                .unwrap()
                .to_string_lossy()
                .starts_with(".vector-work-")
        })
        .collect()
}

/// Run a conversion that must fail with a message containing `expected`, once into a new
/// destination and once over an existing one, and check that nothing was published or left
/// behind and the existing destination is unchanged.
fn refused(
    input: &Path,
    options: VectorOptions,
    observer: Option<Arc<dyn Observer>>,
    expected: &str,
) {
    let root = tempfile::tempdir().unwrap();
    let parent = root.path().join("out");
    fs::create_dir(&parent).unwrap();
    for existing in [false, true] {
        let output = parent.join(format!("result-{existing}.3tz"));
        if existing {
            fs::write(&output, b"previous archive").unwrap();
        }
        let request =
            VectorRequest::new(input, &output, options.clone()).with_policy(OutputPolicy::Replace);
        let failure = vector_to_archive(request, &RunControl::new(observer.clone())).unwrap_err();
        let message = std::iter::once(&failure.error)
            .chain(&failure.secondary)
            .map(|e| e.message().to_owned())
            .collect::<Vec<_>>()
            .join("; ");
        assert!(message.contains(expected), "{message}");
        if existing {
            assert_eq!(fs::read(&output).unwrap(), b"previous archive");
        } else {
            assert!(!output.exists());
        }
        assert_eq!(workspaces(&parent), Vec::<PathBuf>::new());
        let entries: Vec<_> = fs::read_dir(&parent)
            .unwrap()
            .map(|e| e.unwrap().file_name().into_string().unwrap())
            .collect();
        let allowed: &[&str] = if existing { &["result-true.3tz"] } else { &[] };
        assert_eq!(entries, allowed, "no staging or partial output remains");
    }
}

#[test]
fn invalid_feature_publishes_nothing() {
    let root = tempfile::tempdir().unwrap();
    let source = root.path().join("bowtie.geojson");
    fs::write(
        &source,
        json!({"type":"FeatureCollection","features":[
            {"type":"Feature","id":"good","properties":{},"geometry":{"type":"Point","coordinates":[0,0,0]}},
            {"type":"Feature","id":"bad","properties":{},"geometry":{"type":"Polygon",
                "coordinates":[[[0,0,0],[2,2,0],[2,0,0],[0,2,0],[0,0,0]]]}}]})
        .to_string(),
    )
    .unwrap();
    refused(
        &source,
        VectorOptions {
            source_crs: Some("local".into()),
            ..options(1)
        },
        None,
        "No tileset published",
    );
}

/// Alters every staged payload in the vector workspace as encoding progresses, after the
/// encoder has persisted it and before the forest reads it.
struct Tamper {
    parent: PathBuf,
    alter: fn(&Path),
    done: Mutex<BTreeSet<PathBuf>>,
}

impl Observer for Tamper {
    fn observe(&self, event: &RunEvent<'_>) -> Result<(), JobError> {
        if !matches!(
            event,
            RunEvent::Progress {
                phase: "encoding",
                ..
            }
        ) {
            return Ok(());
        }
        let mut done = self.done.lock().unwrap();
        for workspace in workspaces(&self.parent) {
            let Ok(entries) = fs::read_dir(workspace.join("t")) else {
                continue;
            };
            for entry in entries {
                let path = entry.unwrap().path();
                if path.extension().is_some_and(|e| e == "glb") && done.insert(path.clone()) {
                    (self.alter)(&path);
                }
            }
        }
        Ok(())
    }
}

#[test]
fn staged_payload_mismatch_publishes_nothing() {
    let cases: [(fn(&Path), &str); 3] = [
        (|path| fs::remove_file(path).unwrap(), "is missing"),
        (
            |path| {
                let mut bytes = fs::read(path).unwrap();
                bytes.push(0);
                fs::write(path, bytes).unwrap();
            },
            "bytes; its record declares",
        ),
        (
            |path| {
                let mut bytes = fs::read(path).unwrap();
                *bytes.last_mut().unwrap() ^= 1;
                fs::write(path, bytes).unwrap();
            },
            "has sha256",
        ),
    ];
    for (alter, expected) in cases {
        for (name, levels) in [("m1_a.geojson", 1), ("m1_b.geojson", 4)] {
            let input = fixture(name);
            let root = tempfile::tempdir().unwrap();
            let parent = root.path().join("out");
            fs::create_dir(&parent).unwrap();
            let observer = Arc::new(Tamper {
                parent: parent.clone(),
                alter,
                done: Mutex::new(BTreeSet::new()),
            });
            let output = parent.join("result.3tz");
            fs::write(&output, b"previous archive").unwrap();
            let failure = vector_to_archive(
                VectorRequest::new(&input, &output, options(levels))
                    .with_policy(OutputPolicy::Replace),
                &RunControl::new(Some(observer.clone())),
            )
            .unwrap_err();
            let message = failure.error.message().to_owned();
            assert!(
                message.contains("staged content") && message.contains(expected),
                "{name}: {message}"
            );
            assert!(message.contains("nothing was published"), "{message}");
            assert!(!observer.done.lock().unwrap().is_empty());
            assert_eq!(fs::read(&output).unwrap(), b"previous archive");
            assert_eq!(workspaces(&parent), Vec::<PathBuf>::new());
        }
    }
}

/// An observer fault at `ready_to_publish` aborts after the archive is staged.
struct FailAtPublish;

impl Observer for FailAtPublish {
    fn observe(&self, event: &RunEvent<'_>) -> Result<(), JobError> {
        match event {
            RunEvent::Progress {
                phase: "ready_to_publish",
                ..
            } => Err(JobError::new(
                rusty_tiles::JobErrorKind::InvalidState,
                "observer refuses publication",
            )),
            _ => Ok(()),
        }
    }
}

#[test]
fn observer_fault_at_ready_to_publish_publishes_nothing() {
    refused(
        &fixture("m1_a.geojson"),
        options(1),
        Some(Arc::new(FailAtPublish)),
        "observer refuses publication",
    );
}
